#include "DeviceReader.h"

namespace hub {
// A host peripheral backend. Physical plugin packages are never patched for simulation.
// Deliberately restricted to an isolated mouse test profile; no Windows HID handles.
struct VirtualMouse {
 static bool enabled(){wchar_t value[8]{};GetEnvironmentVariableW(L"HHUB_VIRTUAL_MOUSE",value,8);return mousePortTestProfile()&&std::wstring(value)==L"1";}
 unsigned dpi=800,rate=2,shortCommand=3,longCommand=0x67;bool connected=true,ignoreWrites=false;
 std::vector<unsigned char> vaxeePending,mchosePending,config{0,0x30,0x20,0,0x40,6,0x20,3,0x40,6,0x80,12,0,25,0x10,0xa4,1,0x80,0,0,0,0,0,0,0x10,0,0,0,0x20,0,0,0,0x32,0,0x42,0,0x42,0,0x43,0,0x50,0,0,0};
 struct Session {unsigned model;bool open=false;JsonObject policy;};
 std::map<std::wstring,std::map<std::wstring,Session>> owners;
 static JsonArray descriptors(){return JsonArray::Parse(LR"([{"vendorId":12375,"productId":4099,"productName":"VAXEE XE Wireless · 虚拟设备","usagePage":65285,"usage":1,"inputLength":0,"outputLength":0,"featureLength":64,"featureIds":[14],"inputIds":[],"outputIds":[],"virtual":true,"containerId":"hhub-virtual-vaxee"},{"vendorId":14391,"productId":4107,"productName":"MCHOSE A7 V2 Ultra+ 接收器 · 虚拟设备","usagePage":65281,"usage":1,"inputLength":0,"outputLength":0,"featureLength":66,"featureIds":[17,18],"inputIds":[],"outputIds":[],"virtual":true,"containerId":"hhub-virtual-mchose"}])");}
 void decorate(JsonObject detected){if(!enabled())return;for(auto field:{L"devices",L"peripherals"}){auto list=detected.GetNamedArray(field,JsonArray{});for(unsigned i=list.Size();i>0;--i)if(flag(list.GetObjectAt(i-1),L"virtual"))list.RemoveAt(i-1);if(connected)for(auto const& item:descriptors()){auto info=item.GetObject();auto d=DeviceReader::record(str(info,L"containerId"),str(info,L"productName"),L"mouse",L"虚拟 HID · 正式插件协议");put(d,L"real",false);put(d,L"virtual",true);put(d,L"connected",true);put(d,L"containerId",str(info,L"containerId"));put(d,L"vid",num(info,L"vendorId"));put(d,L"pid",num(info,L"productId"));put(d,L"status",std::wstring(L"虚拟设备 · 不代表实机验证"));put(d,L"profile",std::wstring(L"软件虚拟设备"));list.Append(d);}detected.SetNamedValue(field,list);}}
 template<class Matches> JsonObject transact(std::wstring id,JsonObject plugin,JsonObject request,Matches matches){
  auto op=str(request,L"operation");JsonObject result;put(result,L"transportVersion",2.0);put(result,L"virtual",true);
  if(op==L"closeAll"){owners.erase(id);return result;}
  if(op==L"enumerate"){auto& sessions=owners[id];sessions.clear();JsonArray devices;if(connected){unsigned model=0;for(auto const& item:descriptors()){auto info=item.GetObject();for(auto const& rule:plugin.GetNamedArray(L"hidV2Targets",JsonArray{}))if(matches(rule.GetObject(),(unsigned)num(info,L"vendorId"),(unsigned)num(info,L"productId"),(unsigned)num(info,L"usagePage"),1,str(info,L"productName"))){GUID guid{};check_hresult(CoCreateGuid(&guid));wchar_t key[64]{};StringFromGUID2(guid,key,64);put(info,L"key",std::wstring(key));JsonObject c;put(c,L"usagePage",num(info,L"usagePage"));put(c,L"usage",1.0);JsonArray reports;for(auto const& rid:info.GetNamedArray(L"featureIds")){JsonObject r;r.SetNamedValue(L"reportId",rid);r.SetNamedValue(L"items",JsonArray{});reports.Append(r);}c.SetNamedValue(L"featureReports",reports);c.SetNamedValue(L"inputReports",JsonArray{});c.SetNamedValue(L"outputReports",JsonArray{});c.SetNamedValue(L"children",JsonArray{});JsonArray collections;collections.Append(c);info.SetNamedValue(L"collections",collections);devices.Append(info);sessions.emplace(key,Session{model,false,rule.GetObject()});break;}++model;}}result.SetNamedValue(L"devices",devices);return result;}
  auto owner=owners.find(id);if(owner==owners.end())throw hresult_error(E_ACCESSDENIED,L"请先枚举虚拟设备");auto found=owner->second.find(str(request,L"key"));if(found==owner->second.end())throw hresult_error(E_ACCESSDENIED,L"设备令牌不属于此插件");auto& session=found->second;auto& pending=session.model==0?vaxeePending:mchosePending;
  if(op==L"close"){session.open=false;return result;}if(!connected)throw hresult_error(E_FAIL,L"虚拟设备已拔出");if(op==L"open"){session.open=true;put(result,L"inputAvailable",false);return result;}if(!session.open)throw hresult_invalid_argument(L"虚拟设备尚未打开");if(op==L"poll"){result.SetNamedValue(L"events",JsonArray{});return result;}if(op==L"publishBattery")return result;
  unsigned rid=(unsigned)num(request,L"reportId",999);if((session.model==0&&rid!=14)||(session.model==1&&rid!=17&&rid!=18))throw hresult_error(E_ACCESSDENIED,L"报告 ID 不受虚拟设备支持");
  bool declared=false;for(auto const& value:session.policy.GetNamedArray(L"featureReportIds",JsonArray{}))if(value.GetNumber()==rid)declared=true;if(!declared)throw hresult_error(E_ACCESSDENIED,L"报告 ID 不在插件声明范围内");
  if(op==L"sendFeature"){auto bytes=pluginPacket(str(request,L"data"));if(bytes.size()>65||bytes.size()>num(session.policy,L"maxPayload",1024))throw hresult_invalid_argument(L"报告过长");if(session.model==0){if(bytes.size()<7||bytes[0]!=0xa5)throw hresult_invalid_argument(L"无效 VAXEE 请求");pending=bytes;if(bytes[2]==2&&!ignoreWrites){if(bytes[1]==4)dpi=bytes[5]|bytes[6]<<8;if(bytes[1]==7)rate=bytes[4];}}else{for(auto& b:bytes)b^=255;if(bytes.empty())throw hresult_invalid_argument();auto cmd=bytes[0];if(rid==17){shortCommand=cmd;if(cmd==0x42&&!ignoreWrites&&bytes.size()>5){unsigned sensor=(config[17]&~3)|(bytes[1]&3);for(unsigned i=2;i<=4;i++){unsigned bit=1u<<i;if(bytes[i]==1)sensor|=bit;if(bytes[i]==2)sensor&=~bit;}config[17]=(unsigned char)sensor;}}else{longCommand=cmd;pending=bytes;if(cmd==0x57&&!ignoreWrites&&bytes.size()>=45)config.assign(bytes.begin()+1,bytes.begin()+45);}}return result;}
  if(op!=L"receiveFeature")throw hresult_invalid_argument(L"虚拟设备未实现此操作");std::vector<unsigned char> bytes(session.model==0?64:66);bytes[0]=(unsigned char)rid;
  if(session.model==0){if(pending.size()<7)throw hresult_invalid_argument(L"尚未发送请求");auto cmd=pending[1];std::vector<unsigned char> data{1};switch(cmd){case 10:data={0x11,0x10};break;case 4:data={1,(unsigned char)dpi,(unsigned char)(dpi>>8)};break;case 7:data={(unsigned char)rate};break;case 11:data={13};break;case 16:data={0};break;case 1:data={1,2};break;}bytes[1]=0xa5;bytes[2]=cmd;bytes[3]=3;bytes[4]=1;bytes[5]=(unsigned char)data.size();std::copy(data.begin(),data.end(),bytes.begin()+6);}
  else{unsigned cmd=rid==17?shortCommand:longCommand;std::vector<unsigned char> data;if(rid==17){if(cmd==3)data={1,0x37,0x38,0x0b,0x10,1,0};if(cmd==4)data={8,'V','I','R','T','U','A','L','1'};if(cmd==6)data={0x37,0x38,0x21,0x40,5,0x2e,2,4,9,0x29,0,0x2c};}else if(cmd==0x67)data=config;else if(cmd==0x68)data={pending.size()>1?pending[1]:(unsigned char)0,'P','r','o','f','i','l','e',0};bytes[1]=(unsigned char)(cmd^255);for(unsigned i=0;i<data.size();i++)bytes[i+2]=data[i]^255;}
  std::wstring hex;wchar_t token[4]{};for(auto b:bytes){swprintf_s(token,L"%02X",b);if(!hex.empty())hex+=L' ';hex+=token;}put(result,L"data",hex);return result;
 }
};
}
